; tables.s -- lookup tables and box artwork ($6000-$7DFF, tracks 3-4)
; Regenerated by tools/gen.py from the original disk; see README.md.

;---------------------------------------------------------------------------
; TABLES (tracks 3-4, $6000-$7DFF).
;
; Quarter squares for mul8x8: sqr = floor(n*n/4) for n = 0..511,
; sqrm = floor((n-255)^2/4), so sqrm+X+(~A) = sq(X-A).
;---------------------------------------------------------------------------
sqr_lo:
        .repeat 512, N
        .byte   <(N*N/4)
        .endrepeat
sqr_hi:
        .repeat 512, N
        .byte   >(N*N/4)
        .endrepeat
sqrm_lo:
        .repeat 512, N
        .byte   <((N-255)*(N-255)/4)
        .endrepeat
sqrm_hi:
        .repeat 512, N
        .byte   >((N-255)*(N-255)/4)
        .endrepeat

