;---------------------------------------------------------------------------
; HGR row address tables: low byte, high byte for page 1, page 2 and the $A000 copy.
;---------------------------------------------------------------------------
; HGR row address = $2000 + (y & 7)*$400 + ((y >> 3) & 7)*$80 + (y >> 6)*$28
row_lo:
        .repeat 192, ROW
        .byte   <($2000 + (ROW & 7) * $400 + ((ROW >> 3) & 7) * $80 + (ROW >> 6) * $28)
        .endrepeat
row_hi1:
        .repeat 192, ROW
        .byte   >($2000 + (ROW & 7) * $400 + ((ROW >> 3) & 7) * $80 + (ROW >> 6) * $28)
        .endrepeat
row_hi2:                                ; page 2 = page 1 + $2000
        .repeat 192, ROW
        .byte   >(($2000 + (ROW & 7) * $400 + ((ROW >> 3) & 7) * $80 + (ROW >> 6) * $28) + $2000)
        .endrepeat
row_hibg:                               ; clean copy = page 1 + $8000
        .repeat 192, ROW
        .byte   >(($2000 + (ROW & 7) * $400 + ((ROW >> 3) & 7) * $80 + (ROW >> 6) * $28) + $8000)
        .endrepeat

;---------------------------------------------------------------------------
; sprite column pointers: 16 rotation frames x 3 byte columns, into LC RAM.
;---------------------------------------------------------------------------
spr_c0_lo:
        .repeat 16, F
        .byte   <(sprites + F*252 + 0*84)
        .endrepeat
spr_c0_hi:
        .repeat 16, F
        .byte   >(sprites + F*252 + 0*84)
        .endrepeat
spr_c1_lo:
        .repeat 16, F
        .byte   <(sprites + F*252 + 1*84)
        .endrepeat
spr_c1_hi:
        .repeat 16, F
        .byte   >(sprites + F*252 + 1*84)
        .endrepeat
spr_c2_lo:
        .repeat 16, F
        .byte   <(sprites + F*252 + 2*84)
        .endrepeat
spr_c2_hi:
        .repeat 16, F
        .byte   >(sprites + F*252 + 2*84)
        .endrepeat

